import json, subprocess, warnings
warnings.filterwarnings("ignore")
from TTS.utils.synthesizer import Synthesizer
from hts_close import close_voice
lines = [
 "रिपोर्ट में गांठ लिखा है? डॉक्टर ने बायोप्सी करवाने को कहा है, और मन में डर है? घबराइए मत. बायोप्सी क्या है, और कैसे होती है, आखिर तक देखिए.",
 "बायोप्सी में शरीर से टिश्यू का एक बहुत छोटा टुकड़ा, या कुछ कोशिकाएं निकाली जाती हैं. फिर पैथोलॉजिस्ट, यानी लैब के विशेषज्ञ डॉक्टर, उसे माइक्रोस्कोप से जांचते हैं.",
 "याद रखिए, बायोप्सी का मतलब कैंसर नहीं होता. यह संक्रमण, सूजन, टीबी, और कई दूसरी बीमारियों की पहचान में भी मदद करती है. बायोप्सी इसलिए की जाती है, ताकि सही पहचान हो सके.",
 "बायोप्सी के कई तरीके हैं. पतली सुई से कोशिकाएं, जिसे एफ एन ए सी कहते हैं. मोटी सुई से टिश्यू का टुकड़ा, जिसे ट्रूकट या कोर बायोप्सी कहते हैं. अल्ट्रासाउंड या सी टी स्कैन की मदद से, सुई सही जगह तक पहुंचाई जाती है. त्वचा की पंच बायोप्सी. और कभी ऑपरेशन से पूरी गांठ निकालकर जांच.",
 "तैयारी कैसे करें? डॉक्टर को अपनी सभी दवाएं बताएं, खासकर खून पतला करने की दवा. कोई दवा रोकनी हो, तो सिर्फ डॉक्टर बताएंगे. कुछ जांचों में खाली पेट आना होता है. एलर्जी या प्रेगनेंसी हो, तो ज़रूर बताएं. और साथ में किसी को लेकर आएं.",
 "क्या दर्द होता है? ज़्यादातर बायोप्सी में सुन्न करने की दवा दी जाती है, इसलिए ज़्यादा दर्द नहीं होता. बाद में थोड़ा दर्द या नील पड़ सकता है. अगर खून बहना न रुके, सूजन, लाली या बुखार हो, तो तुरंत डॉक्टर से संपर्क करें.",
 "अब लैब में इस टुकड़े का सफर देखिए. पहले इसे फॉर्मेलिन जैसे घोल में सुरक्षित रखा जाता है. फिर इसे मोम में जमाया जाता है. माइक्रोटोम मशीन से, बाल से भी पतली परत काटी जाती है. कांच की स्लाइड पर इसे रंगा जाता है. और फिर पैथोलॉजिस्ट माइक्रोस्कोप से इसे देखते हैं.",
 "रिपोर्ट में आमतौर पर कुछ दिन से एक हफ्ते तक का समय लगता है. कभी कभी ज़्यादा जानकारी के लिए, आई एच सी जैसी खास जांच करनी पड़ती है, जिसमें और समय लग सकता है. रिपोर्ट को हमेशा अपने डॉक्टर से ही समझें.",
 "एक बड़ा मिथक. क्या बायोप्सी से कैंसर फैलता है? अमेरिकन कैंसर सोसाइटी के अनुसार, बायोप्सी से कैंसर फैलना बेहद दुर्लभ है. और बायोप्सी के फायदे, इस छोटे से खतरे से कहीं ज़्यादा हैं. सही इलाज के लिए, सही पहचान ज़रूरी है.",
 close_voice("क्या आपके मन में भी बायोप्सी को लेकर डर था?"),
]
import os
d = os.environ.get("HTS_MODEL", "/tmp/hi/hi/")
s = Synthesizer(tts_checkpoint=d + "fastpitch/best_model.pth", tts_config_path=d + "fastpitch/config.json",
                vocoder_checkpoint=d + "hifigan/best_model.pth", vocoder_config=d + "hifigan/config.json", use_cuda=False)
durs = []
for i, l in enumerate(lines):
    f = f"/tmp/bior_{i}.wav"; s.save_wav(s.tts(l, speaker_name="female"), f)
    subprocess.run(["ffmpeg","-nostdin","-y","-loglevel","error","-i",f,"-af","rubberband=pitch=0.96:formant=preserved,equalizer=f=250:t=q:w=1:g=2,treble=g=-1.5:f=6000",f"/tmp/bio_{i}.wav"],check=True); f=f"/tmp/bio_{i}.wav"
    durs.append(float(subprocess.check_output(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", f]).decode()))
json.dump(durs, open("/tmp/bio_durs.json", "w")); print([round(x, 1) for x in durs], round(sum(durs), 1))
